function validate([wordsDict, word1, word2]) {
  if (!Array.isArray(wordsDict) || wordsDict.length < 1 || wordsDict.length > 100000) return 'wordsDict needs 1 to 10^5 words.';
  const shape = /^[a-z]{1,10}$/;
  if (!wordsDict.every(w => typeof w === 'string' && shape.test(w))) return 'Each word has 1 to 10 lowercase letters.';
  let count1 = 0, count2 = 0;
  for (const w of wordsDict) {
    if (w === word1) count1++;
    if (w === word2) count2++;
  }
  if (count1 === 0 || count2 === 0) return 'word1 and word2 must both appear in wordsDict.';
  if (word1 === word2 && count1 < 2) return 'When word1 equals word2, it must appear at least twice.';
  return null;
}

