function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const pick = list => list[Math.floor(rand() * list.length)];
  const makeWord = maxLength => {
    const length = 1 + Math.floor(rand() * maxLength);
    let word = '';
    for (let k = 0; k < length; k++) word += letters[Math.floor(rand() * (size === 'large' ? 26 : 3))];
    return word;
  };
  for (;;) {
    const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 9);
    const vocabulary = Array.from({ length: size === 'large' ? 40 : 1 + Math.floor(rand() * 4) }, () => makeWord(size === 'large' ? 10 : 2));
    const wordsDict = Array.from({ length: n }, () => pick(vocabulary));
    const word1 = pick(wordsDict);
    const word2 = rand() < 0.3 ? word1 : pick(wordsDict);
    if (word1 === word2 && wordsDict.filter(w => w === word1).length < 2) continue;
    return [wordsDict, word1, word2];
  }
}
